// Reads SETUP_OUTCOME, COMMIT_OUTCOME, COMMITTED and EARLIER_FAILED, and the GitHub run variables.
import { readFileSync } from "node:fs";

const MARKER = "<!-- gbuddy-update-report -->";
const FAILED = "<!-- gbuddy-update-failed -->";

const REMOVED = "Removed, because gbuddy no longer generates them and nobody had edited them:";
const REPLACED = "Replaced, because they had been changed by hand (the earlier text is in the history of this branch):";

